+constexpr size_t INSERTION_SORT_THRESHOLD = 8;
+
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > 0 && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
+}
+
+static void merge_sort_iter(uint32_t* a, uint32_t* tmp, size_t n) {
+    size_t width = 1;
+    while (width < n) {
+        for (size_t i = 0; i < n; i += 2 * width) {
+            size_t lo = i, mid = std::min(i + width, n), hi = std::min(i + 2 * width, n);
+            size_t len = hi - lo;
+            if (len <= INSERTION_SORT_THRESHOLD) {
+                insertion_sort(a + lo, len);
+                continue;
+            }
+            size_t i1 = lo, i2 = mid, j = lo;
+            while (i1 < mid && i2 < hi) tmp[j++] = (a[i2] < a[i1]) ? a[i2++] : a[i1++];
+            while (i1 < mid) tmp[j++] = a[i1++];
+            while (i2 < hi) tmp[j++] = a[i2++];
+            for (size_t k = lo; k < hi; ++k) a[k] = tmp[k];
+        }
+        width *= 2;
+    }
 }

